design_text:
{
  "site_summary": "A fully shaded balcony microclimate safe for curious cats and dogs.",
  "layout_strategy": "Trailing foliage plants on the railing at eye level, lush upright perennials at mid height against the back wall, and a low ground layer along the balcony floor edge for easy pet access.",
  "combination_logic": "This combination merges fine-textured arching fronds with broad glossy leaves and delicate white daisy-like blooms, offering continuous foliage contrast and seasonal autumn flowering.",
  "zones": [
    {
      "zone_name": "Railing Edge",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "on the north-facing railing, 2 hours of filtered morning sun, fully sheltered from harsh afternoon heat.",
      "plants": [
        {
          "scientific_name": "Chlorophytum comosum",
          "common_name": "Spider Plant",
          "why": "Fits the vertical hanging zone perfectly by cascading over the railing.",
          "role_in_combination": "Provides bright linear contrast and arching movement against the darker foliage."
        }
      ],
      "maintenance": [
        "Water thoroughly every 5 days during summer and every 10 days in winter.",
        "Fertilize monthly during spring and summer with a balanced organic liquid feed."
      ]
    },
    {
      "zone_name": "Back Wall Display",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "against the north-facing back wall, deep shade with zero direct sunlight.",
      "plants": [
        {
          "scientific_name": "Aspidistra elatior",
          "common_name": "Cast Iron Plant",
          "why": "Brings robust vertical presence and deep green structure to the mid layer.",
          "role_in_combination": "Anchors the mid layer with broad, architectural leaves that contrast with delicate ferns."
        },
        {
          "scientific_name": "Ageratina altissima",
          "common_name": "White Snakeroot",
          "why": "Thrives in deep shade and introduces seasonal autumn blooms.",
          "role_in_combination": "Adds textural contrast with finely toothed leaves and bright white fluffy flower clusters."
        }
      ],
      "maintenance": [
        "Check soil moisture weekly and water when the top two inches are dry.",
        "Prune back spent flower stems in late winter to encourage fresh spring growth."
      ]
    },
    {
      "zone_name": "Balcony Floor Edge",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "along the north-facing balcony floor edge, low light, easily reachable by the pet.",
      "plants": [
        {
          "scientific_name": "Asplenium bulbiferum",
          "common_name": "Hen and Chickens Fern",
          "why": "Soft, non-toxic fronds invite gentle interaction at floor level.",
          "role_in_combination": "Creates a lush, feathery ground layer that softens the hard floor boundaries."
        },
        {
          "scientific_name": "Chamaedorea elegans",
          "common_name": "Parlor Palm",
          "why": "Provides a gentle, pet-safe tropical texture at the base of the design.",
          "role_in_combination": "Brings fine vertical frond structure contrasting nicely with broader fern leaves."
        },
        {
          "scientific_name": "Cyrtomium falcatum",
          "common_name": "Fish Tail Fern",
          "why": "Adds sturdy, glossy foliage that handles occasional brushing by pets.",
          "role_in_combination": "Contributes unique holly-like leaflet shapes and a deep glossy sheen to the ground layer."
        }
      ],
      "maintenance": [
        "Water every 4 days during warm summer months and weekly in winter.",
        "Remove any bruised or yellowing fronds at the base as needed."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Water all containers thoroughly until drainage occurs",
      "frequency": "Twice a week in summer, weekly in spring and autumn, every 12 days in winter",
      "season": "Year-round"
    },
    {
      "task": "Apply diluted organic liquid fertilizer",
      "frequency": "Every four weeks",
      "season": "Spring and Summer"
    },
    {
      "task": "Inspect foliage for dust buildup and wipe gently with a damp cloth",
      "frequency": "Monthly",
      "season": "Year-round"
    }
  ],
  "care_cautions": [
    "Overwatering the hanging Chlorophytum comosum in the Railing Edge zone can cause root rot due to poor drainage.",
    "The ferns in the Balcony Floor Edge zone require high humidity and may suffer leaf tip browning if exposed to dry indoor heating drafts."
  ],
  "pet_safety_note": "Every plant selected is entirely non-toxic to cats and dogs, and the grazing zone is placed at floor level for safe, accessible enrichment."
}
